/* discouraged: one struct carrying both capabilities beats two linked structs */
typedef struct Widget   { WidgetVtbl const *vptr; int x, y; } Widget;
typedef struct Tickable { TickVtbl const *vptr; void *ctx; } Tickable;

typedef struct Ball {
    Widget   widget;      /* first member: usable as Widget *       */
    Tickable tickable;    /* second capability, callback with ctx   */
} Ball;

static void ball_draw(Widget const *me) { ... }
static void ball_tick(Tickable *me)      { ball_step((Ball *)me->ctx); }
